<div class="container py-4"><h1 class="h3 mb-4">New privacy task</h1><form method="post" action="<?=url('tasks/store')?>" class="card border-0 shadow-sm"><div class="card-body"><input type="hidden" name="client_id" value="<?=(int)$client['id']?>"><?php include __DIR__.'/../partials/csrf.php';?><div class="row g-3"><div class="col-md-8"><label class="form-label">Title *</label><input required name="title" class="form-control"></div><div class="col-md-4"><label class="form-label">Priority</label><select name="priority" class="form-select"><?php foreach(['low','medium','high','critical'] as $v):?><option value="<?=$v?>"><?=ucfirst($v)?></option><?php endforeach;?></select></div><div class="col-12"><label class="form-label">Description</label><textarea name="description" rows="3" class="form-control"></textarea></div><div class="col-md-4"><label class="form-label">Assessment</label><select name="assessment_id" class="form-select"><option value="">None</option><?php foreach($assessments as $a):?><option value="<?=(int)$a['id']?>"><?=e($a['title'])?></option><?php endforeach;?></select></div><div class="col-md-4"><label class="form-label">Assign to</label><select name="assigned_to" class="form-select"><option value="">Unassigned</option><?php foreach($users as $u):?><option value="<?=(int)$u['id']?>"><?=e($u['name'])?></option><?php endforeach;?></select></div><div class="col-md-4"><label class="form-label">Due date</label><input type="date" name="due_date" class="form-control"></div></div></div><div class="card-footer bg-white d-flex justify-content-between"><a href="<?=url('tasks',['client_id'=>(int)$client['id']])?>" class="btn btn-outline-secondary">Cancel</a><button class="btn btn-primary">Create task</button></div></form></div>
